/*
 * Os_Cfg.h
 *
 * GENERATED by generator/gen_rte.py from config/swc/SwcTypes.arxml, config/system/System.arxml,
 * config/ecuc/LightEcu.ecuc.json - do not edit.
 * [Educational Implementation]
 * Corresponds to AUTOSAR OS generator output (OIL / OsConfig -> Os_Cfg.h).
 *
 * OS object identifiers and counts of ECU LightEcu. Included by Os.h (after the OS types), so SWC-
 * independent code like the RTE can name tasks, alarms, events and resources by their ECUC short
 * names. Object ids are the index into the tables of Os_Cfg.c; event masks are one bit each;
 * resource id 0 is the implicit RES_SCHEDULER.
 */
#ifndef OS_CFG_H
#define OS_CFG_H

/* ---- counts (array sizes in Os_Cfg.c, also used by the kernel for its run-time tables) ---- */
#define OS_NUM_TASKS        4u
#define OS_NUM_COUNTERS     1u
#define OS_NUM_ALARMS       2u
#define OS_NUM_RESOURCES    1u
#define OS_NUM_ISRS         1u

/* ---- hooks (OsHooks): the kernel calls a hook only if enabled; bodies are in integration/Os_Hooks.c ---- */
#define OS_USE_STARTUPHOOK   1
#define OS_USE_ERRORHOOK     1
#define OS_USE_SHUTDOWNHOOK  1
#define OS_USE_PRETASKHOOK   0
#define OS_USE_POSTTASKHOOK  0

/* ---- tasks (OsTask): id = index in Os_Config.tasks; the Idle task is internal to the kernel and has no id here ---- */
#define Task_Init              ((TaskType)0u)   /* BASIC, priority 10 */
#define Task_BswMain           ((TaskType)1u)   /* BASIC, priority 4 */
#define Task_LightCtl          ((TaskType)2u)   /* EXTENDED, priority 3 */
#define Task_LightAct          ((TaskType)3u)   /* BASIC, priority 2 */

/* ---- counters / alarms / resources / ISRs ---- */
#define Counter_System         ((CounterType)0u)
#define Alarm_BswMain          ((AlarmType)0u)
#define Alarm_LightCtl20ms     ((AlarmType)1u)
#define Res_EA_Odo             ((ResourceType)1u)   /* ceiling priority 3 */
#define Isr_CanRx              ((ISRType)0u)

/* ---- events (OsEvent): one bit each; the owning task is named in OsTaskEvent ---- */
#define Ev_LightCtl_Timer20ms      ((EventMaskType)0x1u)
#define Ev_LightCtl_VehicleSpeed   ((EventMaskType)0x2u)
#define Ev_LightCtl_ModeSwitch     ((EventMaskType)0x4u)

#endif /* OS_CFG_H */
